            // iteration) + BlockSolveGeneral's own QRCP scratch + per-column thresholds + row scratch
            // for the preconditioner.
            var Mmat     = new floatMxN(s, s, Allocator.Temp, true);
            var Rhs      = new floatMxN(s, s, Allocator.Temp, true);
            var alphaMat = new floatMxN(s, s, Allocator.Temp, true);
