            Mmat.Dispose(); Rhs.Dispose(); alphaMat.Dispose(); betaMat.Dispose();
            coefWork.Dispose(); rhsWork.Dispose(); Rqrcp.Dispose(); Pqrcp.Dispose(); uQrcp.Dispose();
